dia":null,"provenance":{"sources":["https://whc.unesco.org/en/list/1081/"],"subjectKey":"landmark:1081","edition":"geo-v3-2026-11","iso":"MN","confusions":["CN","KP","KR"],"siteId":"1081"}},{"id":"geo-v3-landmarks-a814bf5f0f3cdc74","category":"landmarks","difficulty":2,"prompt":"In welchem Land liegt die UNESCO-Kulturerbestätte „Historic Centre of Agadez“?","options":["Burkina Faso","Niger","Benin","Nigeria"],"correct":1,"enabled":true,"explanation":"„Historic Centre of Agadez“ ist eine UNESCO-Kulturerbestätte in Niger (Afrika). Die UNESCO führt sie unter der Listennummer 1268.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/1268/"],"subjectKey":"landmark:1268","edition":"geo-v3-2026-11","iso":"NE","confusions":["NG","BJ","BF"],"siteId":"1268"}},{"id":"geo-v3-landmarks-8bec891f57efa8f8","category":"landmarks","difficulty":2,"prompt":"In welchem Land liegt die UNESCO-Kulturerbestätte „Flemish Béguinages“?","options":["Niederlande","Luxemburg","Deutschland","Belgien"],"correct":3,"enabled":true,"explanation":"„Flemish Béguinages“ ist eine UNESCO-Kulturerbestätte in Belgien (Europa). Die UNESCO führt sie unter der Listennummer 855.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/855/"],"subjectKey":"landmark:855","edition":"geo-v3-2026-11","iso":"BE","confusions":["LU","NL","DE"],"siteId":"855"}}]$review$::jsonb) as x(id text,category text,difficulty int,prompt text,options jsonb,correct int,explanation text,media jsonb,provenance jsonb)
